import { tags } from "typia";

import { IReviewAnalyticsReviewPreview } from "./IReviewAnalyticsReviewPreview";

/**
 * Review analytics response containing aggregated statistics for a product's reviews. Includes the average star rating (0-5, rounded to 1 decimal), total count of active reviews, breakdown of ratings across all 5 star levels, and a preview of up to 10 most recent reviews with customer information. Only active (non-deleted) reviews are included in all calculations.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IReviewAnalyticsResponse = {
  /**
   * The average star rating for this product, rounded to one decimal place. Calculated from all active (non-deleted) reviews. Returns null if the product has no reviews.
   *
   * @x-autobe-specification Computed value: SUM(rating)/COUNT(*) from ecommerce_mall_reviews where product_id matches and deleted_at IS NULL, rounded to 1 decimal place. Returns null when no reviews exist (division by zero handled). Range: 0.0 to 5.0 based on valid rating values in reviews table.
   */
  average_rating: (number & tags.Minimum<0> & tags.Maximum<5>) | null;

  /**
   * The total number of active (non-deleted) reviews for this product.
   *
   * @x-autobe-specification Computed value: COUNT(*) from ecommerce_mall_reviews where product_id matches and deleted_at IS NULL. Returns integer >= 0. Counts only active reviews, excluding soft-deleted records.
   */
  total_count: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Breakdown of review counts by star rating. Contains five fields: rating5_count, rating4_count, rating3_count, rating2_count, and rating1_count, representing how many reviews have each star rating.
   *
   * @x-autobe-specification Computed object with 5 keys (rating5_count, rating4_count, rating3_count, rating2_count, rating1_count). Each key holds COUNT(*) of reviews from ecommerce_mall_reviews where product_id matches, deleted_at IS NULL, and rating equals the key number. All counts are >= 0 and sum to total_count.
   */
  rating_distribution: {
    rating5_count: number & tags.Type<"int32"> & tags.Minimum<0>;
    rating4_count: number & tags.Type<"int32"> & tags.Minimum<0>;
    rating3_count: number & tags.Type<"int32"> & tags.Minimum<0>;
    rating2_count: number & tags.Type<"int32"> & tags.Minimum<0>;
    rating1_count: number & tags.Type<"int32"> & tags.Minimum<0>;
  };

  /**
   * Up to 10 most recent review previews for this product, sorted by creation date (newest first). Each review includes the customer's display name, star rating, optional text content, and creation timestamp.
   *
   * @x-autobe-specification Computed array with max 10 items. SELECT id, customer.display_name, rating, text_content, created_at FROM ecommerce_mall_reviews INNER JOIN ecommerce_mall_customers ON reviews.customer_id=customers.id WHERE reviews.product_id=:productId AND reviews.deleted_at IS NULL ORDER BY reviews.created_at DESC LIMIT 10. Each item represents one active review with customer display name, rating, optional text, and creation timestamp.
   */
  recent_reviews: IReviewAnalyticsReviewPreview[] & tags.MaxItems<10>;
};
